# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUR\'AN VE SÜNNETTE HAYVAN HAKLARI VE MERHAMET AHLAKI (TDB.1.3.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">KUR\'AN VE SÜNNETİN TEMEL İLKELERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• En\'âm 38: «Hayvanlar ve kuşlar da sizin gibi birer ümmettir»</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Her canlıya yapılan iyilikte sadaka sevabı vardır (Hadis)</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Hayvanlara gücünün üstünde yük yüklemek yasaklanmıştır</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Canlı hayvanı hedef tahtası yapmak ve dövüştürmek haramdır</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• Kuş yuvalarını bozmak ve zevk için avlanmak men edilmiştir</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İSLAM MEDENİYETİNDE MERHAMET KURUMLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Cami ve konak cephelerinde zarif taş «Kuş Evleri / Köşkleri»</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• Göçmen kuşlar için kurulan «Gurabâhâne-i Laklakan» (Bursa)</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• Kışın dağlara vahşi hayvanlar için yem bırakan vakıflar</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• Yaşlanan yük hayvanlarının bakımı için kurulan çayır vakıfları</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Sokak hayvanları için kaldırım taşlarına oyulan su çukurları</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Merhamet etmeyene Allah da merhamet etmez; yeryüzündekilere merhamet edin ki göktekiler de size merhamet etsin.»</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DOĞAL KAYNAKLARIN KORUNMASI: İKTİSAT VE İSRAF YASAĞI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">İSRAF VE SAVURGANLIK YASAĞI</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• A\'râf 31: «Yiyiniz, içiniz fakat israf etmeyiniz»</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• İsrâ 27: «Çünkü saçıp savuranlar şeytanların kardeşleridir»</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Furkân 67: Harcamada ne israf ne cimrilik; orta yol (itidal)</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• Su İsrafı: «Akan bir nehrin kenarında olsan bile suyu israf etme»</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Doğal kaynakların tahribi gelecek nesillerin «kul hakkı»dır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">GÜNLÜK YAŞAMDA TASARRUF VE ÇEVRE BİLİNCİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Su Tasarrufu: Abdestte ve temizlikte suyu ölçülü kullanma</text>\n  <text x="370" y="112" font-size="11.2" fill="#581c87">• Gıda Tasarrufu: İhtiyaç kadar alma, ekmek ve yemek atığını önleme</text>\n  <text x="370" y="136" font-size="11.2" fill="#581c87">• Enerji Tasarrufu: Gereksiz aydınlatma ve ısıtmayı kapatma</text>\n  <text x="370" y="160" font-size="11.2" fill="#581c87">• Sıfır Atık: Plastik kirliliğini azaltma ve geri dönüşüm</text>\n  <text x="370" y="184" font-size="11.2" fill="#581c87">• İhtiyaç fazlasını infak ve paylaşma kültürüyle değerlendirme</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İktisat (tutumluluk), nimetin kıymetini bilerek onu yaratılış amacına ve ölçüsüne uygun kullanmaktır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YEŞİLİ KORUMA VE İSLAM ÇEVRE AHLAKININ BÜTÜNCÜL ÖZETİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">AĞAÇLANDIRMA VE KORUMA BÖLGELERİ (HİMÂ)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• «Kıyametin kopacağını bilseniz bile elinizdeki fidanı dikiniz»</text>\n  <text x="35" y="112" font-size="11.2" fill="#713f12">• Dikilen ağaçtan insan, kuş ve hayvan yedikçe sadaka yazılır</text>\n  <text x="35" y="136" font-size="11.2" fill="#713f12">• Harem ve Himâ: Mekke, Medine ve Tâif\'in koruma alanı ilanı</text>\n  <text x="35" y="160" font-size="11.2" fill="#713f12">• Savaşta dahi meyve ağaçlarının ve ekinlerin yakılması yasaktır</text>\n  <text x="35" y="184" font-size="11.2" fill="#713f12">• İhyâü\'l-Mevât: Çorak arazileri ağaçlandırıp tarıma kazandırma</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">ÇEVRE BÖLÜMÜNÜN TEMEL KAVRAMLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Sünnetullah &amp; Mizan: Evrendeki ilahi yasa ve ekolojik ölçü</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• Emanet &amp; Hilafet: Doğanın insana korunmak üzere verilmesi</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• Fesat: İnsan eliyle karada ve denizde dengenin bozulması (Rûm 41)</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• Tahâret &amp; Nezâfet: Maddi-manevi temizlik ve çevreyi kirletmeme</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• İktisat &amp; Sadaka-i Câriye: Tasarruf ve kalıcı çevre hayırları</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İslam çevre ahlakı; doğayı sömürülecek bir mülk değil, korunacak ilahi bir emanet ve ayet olarak görür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
